import { inject, Injectable, signal, computed } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { I18nService } from '../../../core/i18n/i18n.service';
import { Course } from '../models/course.model';

/** Shape of public/courses/catalog.json (generated by scripts/generate-catalog.mjs). */
interface Catalog {
  courses: Course[];
}

interface CourseSection {
  id: string;
  title: string;
  content: string;
}

@Injectable({
  providedIn: 'root'
})
export class CourseService {
  private http = inject(HttpClient);
  private i18n = inject(I18nService);
  private raw = signal<Course[]>([]);
  /** Catalogue with title and description in the active language (English when untranslated). */
  private catalog = computed(() => {
    const lang = this.i18n.lang();
    return this.raw().map(c => ({ ...c, ...(c.i18n?.[lang] ?? {}) }));
  });
  private failed = signal(false);

  readonly courses = this.catalog;
  /** True when the catalogue could not be loaded. */
  readonly loadFailed = this.failed.asReadonly();
  /** Resolves once the catalogue has been loaded (or has failed). */
  readonly ready: Promise<void> = this.loadCatalog();

  /** Colour accent (0-3) of a course, stable for a given catalogue; shared by tiles, cards and headers. */
  accentOf(id: string): number {
    const i = this.catalog().findIndex(c => c.id === id);
    return i < 0 ? 0 : i % 4;
  }

  getCourseById(id: string): Course | undefined {
    return this.catalog().find(c => c.id === id);
  }

  /** URL of a chapter file in the active language, falling back to the base (English) file. */
  chapterPath(course: Course, file: string): string {
    const lang = this.i18n.lang();
    const translated = course.langs?.[lang]?.includes(file)
      ? file.replace(/\.md$/i, `.${lang}.md`)
      : file;

    return `courses/${course.id}/${translated}`;
  }

  /**
   * Loads a course's chapters concurrently while preserving catalogue order.
   * A missing chapter is skipped without preventing the other chapters from loading.
   */
  async loadCourse(courseId: string): Promise<CourseSection[]> {
    await this.ready;

    const course = this.getCourseById(courseId);
    if (!course) {
      console.warn(`Cours introuvable : ${courseId}`);
      return [];
    }

    const results = await Promise.all(
      (course.chapters ?? []).map(async (file): Promise<CourseSection | null> => {
        try {
          const content = await firstValueFrom(
            this.http.get(this.chapterPath(course, file), { responseType: 'text' })
          );
          const id = file.replace(/\.md$/i, '');
          const title = id
            .replace(/[-_]/g, ' ')
            .replace(/\b\w/g, character => character.toUpperCase());

          return { id, title, content };
        } catch (error) {
          console.warn(`Chapitre indisponible : ${file}`, error);
          return null;
        }
      })
    );

    return results.filter((section): section is CourseSection => section !== null);
  }

  private async loadCatalog(): Promise<void> {
    try {
      const data = await firstValueFrom(this.http.get<Catalog>('courses/catalog.json'));
      this.raw.set(data.courses ?? []);
    } catch (err) {
      console.error(`Catalogue introuvable : ${err}`);
      this.failed.set(true);
    }
  }
}
